"""Build the run_03 HTML playback review from supplied atlas and socket data.
Place review.html in a preview/ directory beside character/ and vfx/ assets.
The template is frozen inline; no external source reads at runtime.
"""
import argparse
import json
from pathlib import Path

TEMPLATE = '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>ASTRA · painted character and frost</title>\n<style>body{margin:0;background:#11151e;color:#e5e9f1;font:16px/1.5 system-ui}main{max-width:1100px;margin:auto;padding:24px}h1{font-size:28px}label{display:inline-flex;gap:8px;align-items:center;margin:8px 16px 8px 0}select,input,button{background:#253043;color:white;border:1px solid #75809b;padding:8px;font:inherit;border-radius:4px}canvas{width:100%;height:auto;background:#141922;border:1px solid #475367}p{color:#b5c0d4}a{color:#a9ccff}button:disabled{opacity:.5}#seek{width:260px}.strip{overflow:auto}.strip img{max-width:none}</style>\n<main><h1>Painted battle-mage & frost</h1><p>Production review · <span id="counts"></span>. Qualification remains in progress. <a href="../REPORT.md">Report</a></p>\n<label>Mode <select id="mode"><option value="idle">Idle</option><option value="walk">Walk</option><option value="cast">Cast</option><option value="combined">Cast + VFX</option><option value="vfx_cast">VFX cast</option><option value="vfx_travel">VFX travel</option><option value="vfx_impact">VFX impact</option></select></label>\n<label>Direction <select id="direction"><option>S</option><option>SW</option><option>W</option><option>NW</option><option>N</option><option>NE</option><option>E</option><option>SE</option></select></label>\n<label>FPS <input id="fps" type="number" min="1" max="60" value="8"></label>\n<label>Background <select id="background"><option value="#141922">Dark slate</option><option value="#e6e9ef">Light gray</option><option value="#465082">Blue</option></select></label>\n<p><button id="play">Pause</button> <button id="restart">Restart</button> <label>Time <input id="seek" type="range" min="0" max="1800" value="0"></label> <span id="status" role="status">Loading sheets…</span></p>\n<canvas id="frame" width="1024" height="640" aria-label="Animation and combined spell playback"></canvas>\n<p>Combined mode uses cast at 16 fps and effects at 20 fps. The projectile spawns on character frame 6 (index 5), at 312.5 ms. Cast flare begins at 125 ms; travel lasts 600 ms, then impact fades over 500 ms. Combined playback is available for S and E.</p>\n<div class="strip"><img src="../character/turnaround_64px.png" alt="Approved eight-direction turnaround at 64-pixel canvas height"></div></main>\n<script>\nconst data=__ASSET_DATA__;\nconst $=id=>document.getElementById(id),ctx=$(\'frame\').getContext(\'2d\'),images={};let elapsed=0,playing=true,last=null,ready=false;\nconst SPAWN=5/16,FLARE_START=2/16,TRAVEL=.6,END=SPAWN+TRAVEL+10/20;\nfunction combinedState(t){return{character:Math.min(11,Math.floor(t*16)),flare:t>=FLARE_START&&t<FLARE_START+8/20?Math.min(7,Math.floor((t-FLARE_START)*20)):null,travel:t>=SPAWN&&t<SPAWN+TRAVEL?Math.floor((t-SPAWN)*20)%6:null,impact:t>=SPAWN+TRAVEL&&t<END?Math.min(9,Math.floor((t-SPAWN-TRAVEL)*20)):null,travelProgress:Math.max(0,Math.min(1,(t-SPAWN)/TRAVEL))};}\nfunction sprite(key,rect,x,y,w=rect[2],h=rect[3],rotation=0,pivot=null){const im=images[key];if(!im)return;ctx.save();ctx.translate(x,y);ctx.rotate(rotation);const p=pivot||[w/2,h/2];ctx.drawImage(im,...rect,-p[0],-p[1],w,h);ctx.restore();}\nfunction available(){const m=$(\'mode\').value,d=$(\'direction\').value;if(m.startsWith(\'vfx_\'))return true;if(m===\'combined\')return [\'S\',\'E\'].includes(d)&&data.character.animations.cast.available[d]===12;return data.character.animations[m].available[d]===data.character.animations[m].count;}\nfunction render(){ctx.fillStyle=$(\'background\').value;ctx.fillRect(0,0,1024,640);if(!ready)return;const m=$(\'mode\').value,d=$(\'direction\').value,fps=Math.max(1,Number($(\'fps\').value)||8);if(!available()){$(\'status\').textContent=\'This sequence is still being produced.\';return;}\n if(m===\'combined\'){\n  const t=elapsed%1.8,s=combinedState(t),row=data.character.directions.indexOf(d),offset=[120,20];\n  sprite(\'c_cast\',[s.character*512,row*512,512,512],...offset,512,512,0,[0,0]);\n  const socket=data.sockets[d][s.character]||data.sockets[d][5],origin=data.sockets[d][5].map((v,i)=>v+offset[i]);\n  if(s.flare!==null)sprite(\'v_cast\',[s.flare*256,0,256,256],socket[0]+offset[0],socket[1]+offset[1]);\n  const target=d===\'E\'?[800,origin[1]]:[origin[0]+150,535],angle=Math.atan2(target[1]-origin[1],target[0]-origin[0]);\n  if(s.travel!==null){const p=s.travelProgress;sprite(\'v_travel\',[s.travel*256,0,256,128],origin[0]+p*(target[0]-origin[0]),origin[1]+p*(target[1]-origin[1]),256,128,angle,[170,64]);}\n  if(s.impact!==null)sprite(\'v_impact\',[s.impact*384,0,384,384],...target);\n  $(\'status\').textContent=`${d} · cast ${s.character+1}/12 · ${(t*1000).toFixed(0)} ms · ${s.travel!==null?\'travel\':s.impact!==null?\'impact\':s.flare!==null?\'cast flare\':\'character\'}`;\n }else if(m.startsWith(\'vfx_\')){const key=m.slice(4),a=data.vfx.modules[key],i=a.loop?Math.floor(elapsed*fps)%a.count:Math.min(a.count-1,Math.floor(elapsed*fps));sprite(\'v_\'+key,a.frames[i].rect,512,300);$(\'status\').textContent=`${key} · ${i+1}/${a.count}`;\n }else{const a=data.character.animations[m],i=a.loop?Math.floor(elapsed*fps)%a.count:Math.min(a.count-1,Math.floor(elapsed*fps));sprite(\'c_\'+m,[i*512,data.character.directions.indexOf(d)*512,512,512],512,300);$(\'status\').textContent=`${d} · ${m} ${i+1}/${a.count}`;}\n $(\'seek\').value=Math.round((elapsed%1.8)*1000);\n}\nfunction reset(){elapsed=0;last=null;const m=$(\'mode\').value;$(\'fps\').value=m===\'combined\'||m===\'cast\'?16:m===\'walk\'?10:m===\'idle\'?8:20;$(\'fps\').disabled=m===\'combined\';$(\'play\').disabled=!available();render();}\n$(\'play\').onclick=()=>{playing=!playing;$(\'play\').textContent=playing?\'Pause\':\'Play\';};$(\'restart\').onclick=reset;$(\'mode\').onchange=reset;$(\'direction\').onchange=reset;$(\'background\').onchange=render;$(\'seek\').oninput=()=>{elapsed=Number($(\'seek\').value)/1000;playing=false;$(\'play\').textContent=\'Play\';render();};\nconst loads=[];for(const[k,a]of Object.entries(data.character.animations))loads.push([\'c_\'+k,\'../character/\'+a.sheet]);for(const[k,a]of Object.entries(data.vfx.modules))loads.push([\'v_\'+k,\'../vfx/\'+a.sheet]);\nPromise.all(loads.map(([key,path])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[key]=im;resolve();};im.onerror=reject;im.src=path;}))).then(()=>{ready=true;reset();}).catch(()=>{$(\'status\').textContent=\'A sheet could not load. Keep the preview with the asset folders.\';});\n$(\'counts\').textContent=`${data.character.available_frames}/224 character frames; 24/24 VFX frames`;\nfunction tick(ms){if(last!==null&&playing)elapsed+=(ms-last)/1000;last=ms;render();requestAnimationFrame(tick);}requestAnimationFrame(tick);\n</script></html>\n'

def build_review(character, vfx, sockets, out):
    if not isinstance(character,dict) or 'animations' not in character or 'available_frames' not in character:
        raise ValueError('Character atlas required')
    if not isinstance(vfx,dict) or 'modules' not in vfx:raise ValueError('VFX atlas required')
    data=json.dumps(dict(character=character,vfx=vfx,sockets=sockets),allow_nan=False).replace('<',r'\u003c')
    html=TEMPLATE.replace('__ASSET_DATA__',data)
    target=Path(out);target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)
    return target

def main():
    p=argparse.ArgumentParser()
    for name in ('character','vfx','sockets','out'):p.add_argument('--'+name,required=True)
    a=p.parse_args();read=lambda path:json.loads(Path(path).read_text())
    build_review(read(a.character),read(a.vfx),read(a.sockets),a.out)

if __name__=='__main__':main()
